def transform(g):
    h,w=len(g),len(g[0])
    zc=[j for j in range(w) if all(g[i][j]==0 for i in range(h))]
    s=next(j for j in zc if any(g[i][k]!=0 for i in range(h) for k in range(j+1,w)))
    e=next(j for j in range(s,w) if any(g[i][j]!=0 for i in range(h)))
    left=[row[:s] for row in g]; right=[row[e:] for row in g]
    lw=len(left[0]); out=[row[:] for row in left]; shapes=[]
    seen=set()
    for i in range(h):
        for j in range(len(right[0])):
            if right[i][j]!=0 and (i,j) not in seen:
                col=right[i][j]; q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<len(right[0]) and right[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                mask=tuple(tuple(1 if (y,x) in cells else 0 for x in range(c0,c1+1)) for y in range(r0,r1+1))
                shapes.append((col,mask))
    seen2=set()
    for i in range(h):
        for j in range(lw):
            if left[i][j]==0 and (i,j) not in seen2:
                q=[(i,j)]; seen2.add((i,j)); comp=[]
                while q:
                    y,x=q.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<lw and left[ny][nx]==0 and (ny,nx) not in seen2:
                            seen2.add((ny,nx)); q.append((ny,nx))
                ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                mask=tuple(tuple(1 if (y,x) in comp else 0 for x in range(c0,c1+1)) for y in range(r0,r1+1))
                for col,smask in shapes:
                    if smask==mask:
                        for (y,x) in comp: out[y][x]=col
                        break
    return out

